import React, { useState, useEffect } from "react"
import "./Navbar.scss"

const Navbar = ({ onOpenModal }) => {
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10)
    window.addEventListener("scroll", handleScroll)
    return () => window.removeEventListener("scroll", handleScroll)
  }, [])

  return (
    <nav
      className={`navbar ${scrolled ? "navbar--scrolled" : ""}`}
      role="navigation"
      aria-label="Primary navigation"
    >
      <div className="navbar__inner container">
        <a href="/" className="navbar__logo">
          Staffy Workforce Scheduling
        </a>

        <button
          type="button"
          className={`navbar__hamburger ${mobileOpen ? "active" : ""}`}
          onClick={() => setMobileOpen(!mobileOpen)}
          aria-label="Toggle menu"
          aria-expanded={mobileOpen}
          aria-controls="navbar-menu"
        >
          <span /><span /><span />
        </button>

        <div id="navbar-menu" className={`navbar__menu ${mobileOpen ? "navbar__menu--open" : ""}`}>
          <ul className="navbar__links">
            <li><a href="#problem" onClick={() => setMobileOpen(false)}>Problem</a></li>
            <li><a href="#solution" onClick={() => setMobileOpen(false)}>Solution</a></li>
            <li><a href="#features" onClick={() => setMobileOpen(false)}>Features</a></li>
            <li><a href="#difference" onClick={() => setMobileOpen(false)}>Why Us</a></li>
            <li><a href="#use-case" onClick={() => setMobileOpen(false)}>Use Case</a></li>
          </ul>
          <div className="navbar__actions">
            <a href="#pilot" className="navbar__link-cta" onClick={() => setMobileOpen(false)}>
              Book a Demo
            </a>
            <button
              type="button"
              className="btn btn--dark btn--sm"
              onClick={() => { onOpenModal(); setMobileOpen(false) }}
            >
              Request Pilot Access
            </button>
          </div>
        </div>
      </div>
    </nav>
  )
}

export default Navbar
